insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-st-121","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"If a flask holds $3.011 \\times 10^{23}$ molecules of nitrogen, the amount of $\\mathrm{N_2}$ in that flask is","options":["0.25 mol","0.50 mol","1.00 mol","2.00 mol"],"answer_index":1,"explanation":"$N / N_A = 3.011 \\times 10^{23} / 6.022 \\times 10^{23} = 0.50$ mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro"},{"id":"che-st-122","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One mole of helium atoms and one mole of hydrogen molecules agree in","options":["total mass","number of elementary entities counted as ‘one mole’","number of atoms","density at STP"],"answer_index":1,"explanation":"A mole always contains $N_A$ of the named entities: He atoms or $\\mathrm{H_2}$ molecules.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro"},{"id":"che-st-123","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An STP sample of ammonia occupying 11.2 L contains molecules numbering","options":["$6.022 \\times 10^{23}$","$3.011 \\times 10^{23}$","$1.505 \\times 10^{23}$","$12.044 \\times 10^{23}$"],"answer_index":1,"explanation":"11.2 L at STP is 0.50 mol, so the molecule count is $0.50\\,N_A = 3.011 \\times 10^{23}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro"},{"id":"che-st-124","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 4.4 g portion of carbon dioxide is analysed for atoms. Taking $M(\\mathrm{CO_2}) = 44\\ \\mathrm{g\\,mol^{-1}}$, the total number of atoms present is","options":["$0.1\\,N_A$","$0.3\\,N_A$","$N_A$","$3\\,N_A$"],"answer_index":1,"explanation":"4.4 g is 0.10 mol of $\\mathrm{CO_2}$; each molecule has 3 atoms, giving $0.30\\,N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro"},{"id":"che-st-125","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Compare 16 g of methane with 16 g of dioxygen. The sample that holds more molecules is","options":["the methane sample","the dioxygen sample","neither; the molecule counts are equal","impossible to decide without density"],"answer_index":0,"explanation":"16 g $\\mathrm{CH_4}$ is 1.0 mol of molecules; 16 g $\\mathrm{O_2}$ is only 0.50 mol, so methane has twice as many molecules.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro"},{"id":"che-st-126","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A gas burette delivers 2.24 L of hydrogen, measured at STP. The amount of $\\mathrm{H_2}$ collected is","options":["0.010 mol","0.10 mol","1.0 mol","2.0 mol"],"answer_index":1,"explanation":"Moles $= 2.24 / 22.4 = 0.10$ mol at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro"},{"id":"che-st-127","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A sealed ampoule contains $3.011 \\times 10^{23}$ molecules of dinitrogen. The mass of that $\\mathrm{N_2}$ sample is","options":["7 g","14 g","28 g","56 g"],"answer_index":1,"explanation":"The count is 0.50 mol; mass $= 0.50 \\times 28 = 14$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro"},{"id":"che-st-128","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Eight grams of dioxygen and seven grams of dinitrogen are compared atom by atom. The two samples contain","options":["equal numbers of molecules and equal numbers of atoms","equal numbers of molecules but different numbers of atoms","different numbers of molecules but equal numbers of atoms","neither equal molecules nor equal atoms"],"answer_index":0,"explanation":"Both are 0.25 mol of diatomic molecules, so both have $0.25\\,N_A$ molecules and $0.50\\,N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro"},{"id":"che-st-129","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 0.25 mol sample of $\\mathrm{Ca_3(PO_4)_2}$ is examined. The number of oxygen atoms in the sample is","options":["$0.25\\,N_A$","$1.00\\,N_A$","$2.00\\,N_A$","$8.00\\,N_A$"],"answer_index":2,"explanation":"Each formula unit has 8 oxygen atoms, so $0.25 \\times 8 = 2.00$ mol of O atoms, i.e. $2.00\\,N_A$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"mole-avogadro"},{"id":"che-st-130","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Among 8 g $\\mathrm{O_2}$, 7 g $\\mathrm{N_2}$, 4 g $\\mathrm{He}$ and 9 g $\\mathrm{H_2O}$, the largest number of atoms is present in","options":["8 g $\\mathrm{O_2}$","7 g $\\mathrm{N_2}$","4 g $\\mathrm{He}$","9 g $\\mathrm{H_2O}$"],"answer_index":3,"explanation":"Atom amounts are 0.50, 0.50, 1.0 and 1.5 mol respectively; 9 g water therefore has the most atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"mole-avogadro"},{"id":"che-st-131","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Using H = 1, S = 32 and O = 16, the molar mass of sulphuric acid $\\mathrm{H_2SO_4}$ is","options":["82 g mol$^{-1}$","98 g mol$^{-1}$","114 g mol$^{-1}$","64 g mol$^{-1}$"],"answer_index":1,"explanation":"$2(1) + 32 + 4(16) = 98$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-132","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Calcium carbonate $\\mathrm{CaCO_3}$ (Ca = 40, C = 12, O = 16) has a formula mass of","options":["50 u","84 u","100 u","116 u"],"answer_index":2,"explanation":"$40 + 12 + 48 = 100$ u.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-133","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The percentage by mass of oxygen in water is closest to","options":["11.1%","50%","88.9%","94.1%"],"answer_index":2,"explanation":"Oxygen contributes 16 of the 18 g in one mole of $\\mathrm{H_2O}$, i.e. $16/18 \\times 100 = 88.9\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-134","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In methane, the mass percent of carbon (C = 12, H = 1) works out to","options":["25%","50%","75%","80%"],"answer_index":2,"explanation":"Carbon is 12 g in 16 g of $\\mathrm{CH_4}$, so $12/16 \\times 100 = 75\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-135","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Carbon dioxide is assigned a molecular mass of 44 u because that value equals","options":["12 + 16","12 + 2(16)","2(12) + 16","12 + 32 + 16"],"answer_index":1,"explanation":"One C and two O atoms give $12 + 32 = 44$ u.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-136","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Ammonia’s gram-molecular mass, with N = 14 and H = 1, is","options":["15 g","16 g","17 g","18 g"],"answer_index":2,"explanation":"$14 + 3(1) = 17$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-137","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen’s share of the mass of water, expressed as a percentage, is","options":["5.6%","11.1%","16.0%","18.0%"],"answer_index":1,"explanation":"Two grams of H in 18 g of water give $2/18 \\times 100 = 11.1\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-138","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Solid sodium hydroxide (Na = 23, O = 16, H = 1) has a molar mass of","options":["23 g mol$^{-1}$","39 g mol$^{-1}$","40 g mol$^{-1}$","58 g mol$^{-1}$"],"answer_index":2,"explanation":"$23 + 16 + 1 = 40$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent"},{"id":"che-st-139","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The calcium content of pure $\\mathrm{CaCO_3}$ (M = 100 g mol$^{-1}$) by mass percent is","options":["12%","40%","48%","60%"],"answer_index":1,"explanation":"40 g of Ca in 100 g of carbonate is a 40% calcium assay.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent"},{"id":"che-st-140","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Urea, $\\mathrm{NH_2CONH_2}$ (M = 60 g mol$^{-1}$), is valued as a fertiliser for nitrogen. The nitrogen mass percent in urea is","options":["23.3%","46.7%","53.3%","60.0%"],"answer_index":1,"explanation":"Two N atoms contribute 28 g in 60 g, so $28/60 \\times 100 = 46.7\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-st-121","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-122","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-123","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-124","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-125","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-126","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-127","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-128","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-129","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-130","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-131","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-132","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-133","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-134","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-135","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-136","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-137","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-138","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-139","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-140","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
